import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        st = new StringTokenizer(br.readLine());
        int a = Integer.parseInt(st.nextToken());
        int ta = Integer.parseInt(st.nextToken());

        st = new StringTokenizer(br.readLine());
        int b = Integer.parseInt(st.nextToken());
        int tb = Integer.parseInt(st.nextToken());

        String[] timeParts = br.readLine().split(":");
        int hh = Integer.parseInt(timeParts[0]);
        int mm = Integer.parseInt(timeParts[1]);
        int simionStart = hh * 60 + mm;
        int simionEnd = simionStart + ta;

        int count = 0;

        // Buses from B to A that departed before Simion arrives at B
        // and whose arrival time at A is after Simion departs from A.
        // A bus departing B at time t_b arrives at A at t_b + tb.
        // For Simion to meet it on the way:
        //   t_b < simionEnd (departs B before Simion arrives at B)
        //   t_b + tb > simionStart (arrives at A after Simion departs A)
        // So t_b must be in (simionStart - tb, simionEnd)

        // Generate all buses from B that departed between 05:00 and 23:59
        int busStartB = 5 * 60; // 05:00
        int busEndB = 23 * 60 + 59; // 23:59

        // First bus from B that could be in range
        int firstBus = busStartB;
        // Find the first bus >= (simionStart - tb + 1)
        int lowerBound = simionStart - tb + 1;
        int upperBound = simionEnd - 1;

        // Calculate first bus from B that departs >= lowerBound
        if (lowerBound <= busEndB) {
            int firstIn = ((lowerBound - busStartB + b - 1) / b) * b + busStartB;
            if (firstIn < busStartB) firstIn = busStartB;
            if (firstIn <= upperBound && firstIn <= busEndB) {
                // Count buses from firstIn to upperBound, step b
                int lastIn = ((upperBound - busStartB) / b) * b + busStartB;
                if (lastIn > upperBound) lastIn -= b;
                if (lastIn >= firstIn) {
                    count += (lastIn - firstIn) / b + 1;
                }
            }
        }

        System.out.println(count);
    }
}
